# AUTO-GENERATED by Claude Code
# Purpose: Search smash-tube.com for Smash Ultimate match videos on YouTube and print them
# (via ds.data.raw.smashtube). Characters are SmashDb char ids.
#
# Example CLI Commands:
#   0. By player:            uv run scripts/smashtube_videos.py --player-1 Sparg0
#   1. Player vs character:  uv run scripts/smashtube_videos.py --player-1 Sparg0 --char-2 fox
#   2. Character matchup:    uv run scripts/smashtube_videos.py --char-1 fox --char-2 cloud
#   3. Event text, region:   uv run scripts/smashtube_videos.py --search-term Kagaribi
#   4. Page 2, raw JSON:     uv run scripts/smashtube_videos.py --player-1 Sparg0 --page 2
# ---------------------------------------------------------------------------
from __future__ import annotations

from typing import Annotated

import typer
from ds.data.raw.smashtube import search_videos
from rich import print as rprint

app = typer.Typer()


@app.command()
def main(
    player_1: Annotated[str, typer.Option(help="A player's tag, eg Sparg0")] = "",
    player_2: Annotated[str, typer.Option(help="The opponent's tag, eg acola")] = "",
    char_1: Annotated[str, typer.Option(help="SmashDb char id, eg little_mac")] = "",
    char_2: Annotated[str, typer.Option(help="SmashDb char id, eg cloud")] = "",
    search_term: Annotated[str, typer.Option(help="Free text, eg an event name (20 chars max)")] = "",
    region: Annotated[str, typer.Option(help="Japan, NA, EU or Other")] = "",
    page: Annotated[int, typer.Option(help="Result page, from 1 (10 videos each)")] = 1,
    json: Annotated[bool, typer.Option("--json", help="Print the raw result as JSON")] = False,
) -> None:
    """Search smash-tube.com; give at least one filter."""
    try:
        result = search_videos(player_1, player_2, char_1, char_2, search_term, region, page)
    except ValueError as e:
        raise typer.BadParameter(str(e)) from e
    if json:
        typer.echo(result.model_dump_json(indent=2))
        return
    rprint(f"[bold]{result.total} videos[/bold], page {result.page} of {result.pages}  [dim]{result.source_url}[/dim]")
    for video in result.videos:
        players = f"  [dim]{', '.join(video.players)}[/dim]" if video.players else ""
        rprint(f"  {video.date or '          '}  {video.title}{players}\n              [blue]{video.url}[/blue]")


if __name__ == "__main__":
    app()
